const categories = [
  'power bank 10000mAh e 20000mAh',
  'carregador GaN 65W',
  'carregador USB-C PD 20W',
  'cabo USB-C trançado',
  'fone bluetooth TWS',
  'suporte veicular para celular',
  'hub USB-C',
  'adaptador USB-C'
];

const approvedDomains = [
  'hayamax.com.br',
  'oderco.com.br',
  'martinsatacado.com.br',
  'snd.com.br'
];

const day = Math.floor(Date.now() / 86400000);
return categories.map((category, index) => {
  const domain = approvedDomains[(day + index) % approvedDomains.length];
  return {
    json: {
      category,
      supplier_domain: domain,
      query: `site:${domain} ${category} atacado revenda fornecedor`,
      requested_at: new Date().toISOString()
    }
  };
});

const output = [];
const seen = new Set();

for (const item of $input.all()) {
  const body = item.json ?? {};
  const data = body.data ?? body;
  const rows = Array.isArray(data?.web)
    ? data.web
    : Array.isArray(data)
      ? data
      : Array.isArray(body.web)
        ? body.web
        : [];

  for (const row of rows.slice(0, 5)) {
    const sourceUrl = String(row.url ?? '').trim();
    if (!sourceUrl.startsWith('https://') || seen.has(sourceUrl)) continue;
    seen.add(sourceUrl);

    output.push({
      json: {
        source_url: sourceUrl,
        source_title: String(row.title ?? '').slice(0, 300),
        source_description: String(row.description ?? '').slice(0, 2000),
        source_markdown: String(row.markdown ?? row.content ?? '').slice(0, 12000),
        discovered_at: new Date().toISOString()
      }
    });
  }
}

return output;

const source = $('Expand and Deduplicate Results').item.json;
const response = $json;
const raw = response?.choices?.[0]?.message?.content ?? response?.output_text ?? response?.content ?? '';
const cleaned = String(raw)
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let ai = {};
let parseError = null;
try {
  ai = JSON.parse(cleaned);
} catch (error) {
  parseError = error.message;
}

const asNumber = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const number = Number(String(value).replace(',', '.'));
  return Number.isFinite(number) ? number : null;
};

const cost = asNumber(ai.cost_brl);
const suggestedPrice = asNumber(ai.suggested_price_brl);
const grossMargin = cost !== null && suggestedPrice !== null && suggestedPrice > 0
  ? Number((((suggestedPrice - cost) / suggestedPrice) * 100).toFixed(2))
  : null;
const riskValues = ['low', 'medium', 'high', 'blocked'];
const riskLevel = riskValues.includes(String(ai.risk_level).toLowerCase())
  ? String(ai.risk_level).toLowerCase()
  : 'medium';
const score = Math.max(0, Math.min(100, asNumber(ai.score) ?? 0));
const supplierVerified = ai.supplier_verified === true;
const hasMinimumData = Boolean(ai.product_name && source.source_url && cost !== null);

let decision = 'review';
if (riskLevel === 'blocked') decision = 'block';
else if (riskLevel === 'high') decision = 'reject';
else if (hasMinimumData && supplierVerified && grossMargin !== null && grossMargin >= 35 && score >= 70) decision = 'recommend';

const reasons = Array.isArray(ai.reasons) ? ai.reasons : [];
if (parseError) reasons.push(`AI JSON parse error: ${parseError}`);
if (!hasMinimumData) reasons.push('Dados mínimos insuficientes; revisão humana obrigatória.');

return {
  json: {
    source_url: source.source_url,
    source_title: source.source_title || null,
    supplier_name: ai.supplier_name || null,
    supplier_domain: ai.supplier_domain ? String(ai.supplier_domain).toLowerCase() : null,
    supplier_verified: supplierVerified,
    cnpj: ai.cnpj || null,
    product_name: ai.product_name || source.source_title || null,
    category: ai.category || null,
    cost_brl: cost,
    suggested_price_brl: suggestedPrice,
    gross_margin_pct: grossMargin,
    stock_status: ['in_stock', 'out_of_stock', 'preorder', 'unknown'].includes(ai.stock_status) ? ai.stock_status : 'unknown',
    minimum_order_qty: asNumber(ai.minimum_order_qty),
    shipping_notes: ai.shipping_notes || null,
    risk_level: riskLevel,
    decision,
    score,
    reasons,
    evidence: Array.isArray(ai.evidence) ? ai.evidence : [],
    human_status: 'pending',
    last_seen_at: new Date().toISOString()
  }
};

